package com.github.diogogdias.loulette;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** World-anchored vertical reel cluster drawn over the tile where each monster dies. */
class LouletteOverlay extends Overlay
{
	private static final int CELL_W = 40;
	private static final int CELL_H = 36;
	private static final int VISIBLE_ROWS = 3;
	private static final int GAP = 4;
	private static final int PAD = 4;
	private static final int HEADER = 14;
	private static final int Z_OFFSET = 150;

	private static final Color BG = new Color(20, 20, 20, 215);
	private static final Color WINDOW_BG = new Color(10, 10, 10, 255);
	private static final Color FRAME = new Color(90, 75, 35);
	private static final Color CENTER_LINE = new Color(255, 255, 255, 55);
	private static final Color HEADER_TEXT = new Color(255, 215, 0);
	private static final Font HEADER_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);

	private final Client client;
	private final LoulettePlugin plugin;
	private final LouletteConfig config;
	private final ItemManager itemManager;
	// When true this instance only draws object-anchored chest reels and renders above widgets, so the reel sits
	// over reward-chest interfaces (TOB/ToA/Doom) instead of behind them. The default instance draws the rest on
	// the scene layer.
	private final boolean aboveWidgets;

	@Inject
	LouletteOverlay(Client client, LoulettePlugin plugin, LouletteConfig config, ItemManager itemManager)
	{
		this(client, plugin, config, itemManager, false);
	}

	LouletteOverlay(Client client, LoulettePlugin plugin, LouletteConfig config, ItemManager itemManager,
		boolean aboveWidgets)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.aboveWidgets = aboveWidgets;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(aboveWidgets ? OverlayLayer.ABOVE_WIDGETS : OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final boolean horizontalMode = config.horizontalReel();
		final List<ActiveRoll> rolls = plugin.getActiveRolls();
		final long now = System.currentTimeMillis();
		for (ActiveRoll roll : rolls)
		{
			if (roll.isForceHorizontal())
			{
				continue;
			}
			if (aboveWidgets)
			{
				// This (above-widgets) instance only draws object-anchored chest reels, so they render over the
				// reward-chest interface rather than behind it.
				if (!roll.isForceVertical())
				{
					continue;
				}
			}
			else
			{
				// Object-anchored chest reels are handled by the above-widgets instance.
				if (roll.isForceVertical())
				{
					continue;
				}
				// In global horizontal mode the top-centre overlay handles the remaining (non-chest) reels.
				if (horizontalMode)
				{
					continue;
				}
			}
			drawCluster(g, roll, now);
		}
		return null;
	}

	private void drawCluster(Graphics2D g, ActiveRoll roll, long now)
	{
		final List<SlotReel> reels = roll.getReels();
		if (reels.isEmpty() || roll.getLocation() == null)
		{
			return;
		}

		// Fade the whole cluster out over config.fadeMs() after the result hold, instead of blinking off.
		float alpha = 0f;
		for (SlotReel reel : reels)
		{
			alpha = Math.max(alpha, (float) reel.fadeAlpha(now, config.resultHoldMs(), config.fadeMs()));
		}
		if (alpha <= 0f)
		{
			return;
		}
		final Composite oldComposite = g.getComposite();
		if (alpha < 1f)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		}
		try
		{
			drawClusterBody(g, roll, reels, now);
		}
		finally
		{
			g.setComposite(oldComposite);
		}
	}

	private void drawClusterBody(Graphics2D g, ActiveRoll roll, List<SlotReel> reels, long now)
	{

		final VerticalAnchor anchorMode = config.verticalAnchor();
		LocalPoint lp;
		if (anchorMode == VerticalAnchor.PLAYER && client.getLocalPlayer() != null)
		{
			// Follow the player instead of the death tile.
			lp = client.getLocalPlayer().getLocalLocation();
		}
		else
		{
			// getLocation() is the NPC's south-west footprint tile. When configured to centre, shift to the middle
			// of the footprint (only meaningful for 3x3+; one tile = 128 local units, so the centre is (size-1)*64 NE).
			lp = LocalPoint.fromWorld(client, roll.getLocation());
			if (lp != null && anchorMode == VerticalAnchor.CENTER && roll.getNpcSize() >= 3)
			{
				final int off = (roll.getNpcSize() - 1) * 64;
				lp = new LocalPoint(lp.getX() + off, lp.getY() + off);
			}
		}
		if (lp == null)
		{
			return;
		}
		final Point anchor = Perspective.getCanvasTextLocation(client, g, lp, "", Z_OFFSET);
		if (anchor == null)
		{
			return;
		}

		final double scale = config.slotScale() / 100.0;
		final int cellW = (int) Math.round(CELL_W * scale);
		final int cellH = (int) Math.round(CELL_H * scale);

		final int n = reels.size();
		final int windowH = VISIBLE_ROWS * cellH;
		final int width = PAD * 2 + n * cellW + (n - 1) * GAP;
		final int height = HEADER + PAD * 2 + windowH;
		final int x0 = anchor.getX() - width / 2;
		final int y0 = anchor.getY() - height;

		g.setColor(BG);
		g.fillRoundRect(x0, y0, width, height, 8, 8);
		g.setColor(FRAME);
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(x0, y0, width, height, 8, 8);

		final String header = (n == 1 ? "1 roll" : n + " rolls");
		g.setFont(HEADER_FONT);
		final FontMetrics fm = g.getFontMetrics();
		g.setColor(HEADER_TEXT);
		g.drawString(header, x0 + (width - fm.stringWidth(header)) / 2, y0 + HEADER - 2);

		final Map<Integer, Color> palette = roll.getPalette();
		final Shape oldClip = g.getClip();
		final int windowTop = y0 + HEADER + PAD;
		for (int r = 0; r < n; r++)
		{
			final int x = x0 + PAD + r * (cellW + GAP);
			drawReel(g, reels.get(r), palette, now, x, windowTop, windowH, cellW, cellH, scale);
		}
		g.setClip(oldClip);
	}

	private void drawReel(Graphics2D g, SlotReel reel, Map<Integer, Color> palette, long now, int x, int windowTop,
		int windowH, int cellW, int cellH, double scale)
	{
		final Rectangle window = new Rectangle(x, windowTop, cellW, windowH);

		g.setColor(WINDOW_BG);
		g.fill(window);

		final double pos = reel.position(now);
		final int cellCenterX = x + cellW / 2;
		final int centerRowY = windowTop + windowH / 2;
		final List<Integer> symbols = reel.getSymbols();
		final int size = symbols.size();
		final boolean landed = reel.landed(now);

		g.setClip(window);
		final long base = (long) Math.floor(pos);
		for (int k = -(VISIBLE_ROWS / 2) - 1; k <= (VISIBLE_ROWS / 2) + 1; k++)
		{
			final long s = base + k;
			final int idx = (int) (((s % size) + size) % size);
			final int id = symbols.get(idx);
			final int yCenter = (int) Math.round(centerRowY + (s - pos) * cellH);
			Reels.glow(g, id, palette, cellCenterX, yCenter, false, scale);
			Reels.symbol(g, itemManager, id, 1, cellCenterX, yCenter, scale);
		}
		if (landed)
		{
			final int id = reel.getTargetItemId();
			Reels.glow(g, id, palette, cellCenterX, centerRowY, true, scale);
			Reels.symbol(g, itemManager, id, reel.getQuantity(), cellCenterX, centerRowY, scale);
		}
		g.setClip(null);

		if (landed)
		{
			g.setColor(Reels.colourFor(reel.getTargetItemId(), palette));
			g.setStroke(new BasicStroke(2));
			g.drawRect(x + 1, centerRowY - cellH / 2 + 1, cellW - 2, cellH - 2);
		}
		else
		{
			g.setColor(CENTER_LINE);
			g.setStroke(new BasicStroke(1));
			g.drawLine(x, centerRowY - cellH / 2, x + cellW, centerRowY - cellH / 2);
			g.drawLine(x, centerRowY + cellH / 2, x + cellW, centerRowY + cellH / 2);
		}

		g.setColor(FRAME);
		g.setStroke(new BasicStroke(1));
		g.draw(window);
	}
}

package com.github.diogogdias.loulette;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** CS:GO case-opening style: horizontal reels scrolling under a fixed centre ticker, fixed at the top centre. */
class LouletteReelOverlay extends Overlay
{
	private static final int CELL = 40;
	private static final int STRIP_W = 280;
	private static final int ROW_H = 48;
	private static final int PAD = 6;
	private static final int HEADER = 15;
	private static final int ROW_GAP = 3;

	private static final Color BG = new Color(20, 20, 20, 225);
	private static final Color WINDOW_BG = new Color(10, 10, 10, 255);
	private static final Color FRAME = new Color(90, 75, 35);
	private static final Color TICKER = new Color(255, 215, 0);
	private static final Color HEADER_TEXT = new Color(255, 215, 0);
	private static final Font HEADER_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);

	private final LoulettePlugin plugin;
	private final LouletteConfig config;
	private final ItemManager itemManager;

	@Inject
	LouletteReelOverlay(LoulettePlugin plugin, LouletteConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		// When the global toggle is off, only raids chests (forceHorizontal) use this overlay.
		final boolean all = config.horizontalReel();
		final List<ActiveRoll> rolls = new ArrayList<>();
		for (ActiveRoll roll : plugin.getActiveRolls())
		{
			// Object-anchored chest reels are pinned vertical; never pull them onto the top-centre strip.
			if (roll.isForceVertical())
			{
				continue;
			}
			if (all || roll.isForceHorizontal())
			{
				rolls.add(roll);
			}
		}

		int groups = 0;
		int rows = 0;
		for (ActiveRoll roll : rolls)
		{
			if (!roll.getReels().isEmpty())
			{
				groups++;
				rows += roll.getReels().size();
			}
		}
		if (rows == 0)
		{
			return null;
		}

		final double scale = config.slotScale() / 100.0;
		final int cell = (int) Math.round(CELL * scale);
		final int rowH = (int) Math.round(ROW_H * scale);

		final long now = System.currentTimeMillis();
		final int width = STRIP_W + PAD * 2;
		final int height = PAD * 2 + groups * HEADER + rows * (rowH + ROW_GAP);

		// Fade the strip out over config.fadeMs() after the result hold instead of blinking off. Use the slowest-
		// fading roll so the box stays until the last result has faded.
		float alpha = 0f;
		for (ActiveRoll roll : rolls)
		{
			for (SlotReel reel : roll.getReels())
			{
				alpha = Math.max(alpha, (float) reel.fadeAlpha(now, config.resultHoldMs(), config.fadeMs()));
			}
		}
		if (alpha <= 0f)
		{
			return null;
		}
		final Composite oldComposite = g.getComposite();
		if (alpha < 1f)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		}

		g.setColor(BG);
		g.fillRoundRect(0, 0, width, height, 8, 8);
		g.setColor(FRAME);
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(0, 0, width, height, 8, 8);

		g.setFont(HEADER_FONT);
		final FontMetrics fm = g.getFontMetrics();

		int y = PAD;
		for (ActiveRoll roll : rolls)
		{
			final List<SlotReel> reels = roll.getReels();
			if (reels.isEmpty())
			{
				continue;
			}
			final String header = (reels.size() == 1 ? "1 roll" : reels.size() + " rolls");
			g.setColor(HEADER_TEXT);
			g.drawString(header, PAD + (STRIP_W - fm.stringWidth(header)) / 2, y + HEADER - 3);
			y += HEADER;

			for (SlotReel reel : reels)
			{
				drawStrip(g, reel, roll.getPalette(), now, PAD, y, STRIP_W, rowH, cell, scale);
				y += rowH + ROW_GAP;
			}
		}

		g.setComposite(oldComposite);
		return new Dimension(width, height);
	}

	private void drawStrip(Graphics2D g, SlotReel reel, Map<Integer, Color> palette, long now, int x, int y, int w,
		int h, int cell, double scale)
	{
		final Rectangle strip = new Rectangle(x, y, w, h);
		g.setColor(WINDOW_BG);
		g.fill(strip);

		final double pos = reel.position(now);
		final int centerX = x + w / 2;
		final int rowCenterY = y + h / 2;
		final List<Integer> symbols = reel.getSymbols();
		final int size = symbols.size();
		final boolean landed = reel.landed(now);
		final int half = w / (2 * cell) + 2;

		final Shape oldClip = g.getClip();
		g.setClip(strip);
		final long base = (long) Math.floor(pos);
		for (int k = -half; k <= half; k++)
		{
			final long s = base + k;
			final int idx = (int) (((s % size) + size) % size);
			final int id = symbols.get(idx);
			final int cellX = (int) Math.round(centerX + (s - pos) * cell);
			Reels.glow(g, id, palette, cellX, rowCenterY, false, scale);
			Reels.symbol(g, itemManager, id, 1, cellX, rowCenterY, scale);
		}
		if (landed)
		{
			final int id = reel.getTargetItemId();
			Reels.glow(g, id, palette, centerX, rowCenterY, true, scale);
			Reels.symbol(g, itemManager, id, reel.getQuantity(), centerX, rowCenterY, scale);
		}
		g.setClip(oldClip);

		if (landed)
		{
			g.setColor(Reels.colourFor(reel.getTargetItemId(), palette));
			g.setStroke(new BasicStroke(2));
			g.drawRect(centerX - cell / 2 + 1, y + 2, cell - 2, h - 4);
		}

		// Centre ticker (CS:GO marker)
		g.setColor(TICKER);
		g.setStroke(new BasicStroke(2));
		g.drawLine(centerX, y, centerX, y + h);
		g.fillPolygon(new Polygon(
			new int[]{centerX - 5, centerX + 5, centerX}, new int[]{y, y, y + 7}, 3));
		g.fillPolygon(new Polygon(
			new int[]{centerX - 5, centerX + 5, centerX}, new int[]{y + h, y + h, y + h - 7}, 3));

		g.setColor(FRAME);
		g.setStroke(new BasicStroke(1));
		g.draw(strip);
	}
}

package com.github.diogogdias.loulette;

import java.awt.Color;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.coords.WorldPoint;

/** A roll anchored to the world tile where an NPC died, holding one reel per loot roll. */
@Getter
class ActiveRoll
{
	private final int npcIndex;
	// Re-anchored when a raid chest reel lands, so the slot settles on the player's own chest (their tile) rather
	// than whichever party chest happened to spawn first.
	@Setter
	private WorldPoint location;
	private final long spinStartMs;
	private final String monster;

	private final List<SlotReel> reels = new CopyOnWriteArrayList<>();
	private boolean finalised;

	// Raids chests have no world tile to anchor to, so they always render on the horizontal top-centre reel.
	@Setter
	private boolean forceHorizontal;

	// Anchored to a specific world object the player stands at (a reward chest / loot hole), so it must render
	// vertically over that tile even when the global display mode is set to the horizontal top-centre reel.
	@Setter
	private boolean forceVertical;

	// A raids-chest reel that starts free-spinning when you enter the reward room, before the chest is opened.
	// It lingers on a longer (2x hold) timeout instead of the normal pre-spin timeout.
	@Setter
	private boolean anticipation;

	// A persistent anticipation (CoX): started on the Olm kill and kept spinning until the loot lands, however
	// long that takes (walk to the reward room, open the chest), rather than the short 2x-hold timeout.
	@Setter
	private boolean persistent;

	// Footprint side length of the source NPC (tiles), used to optionally centre the vertical reel. 1 for chests
	// and anything without an NPC.
	@Setter
	private int npcSize = 1;

	// item id -> CS:GO rarity-grade colour for this monster's table
	@Setter
	private Map<Integer, Color> palette = Collections.emptyMap();

	ActiveRoll(int npcIndex, WorldPoint location, long spinStartMs, String monster)
	{
		this.npcIndex = npcIndex;
		this.location = location;
		this.spinStartMs = spinStartMs;
		this.monster = monster;
	}

	void setReels(List<SlotReel> newReels)
	{
		reels.clear();
		reels.addAll(newReels);
		finalised = true;
	}

	boolean done(long now, long lingerMs, long fadeMs)
	{
		if (reels.isEmpty())
		{
			return false;
		}
		for (SlotReel reel : reels)
		{
			if (!reel.expired(now, lingerMs, fadeMs))
			{
				return false;
			}
		}
		return true;
	}
}

package com.github.diogogdias.loulette;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Paint;
import java.awt.RadialGradientPaint;
import java.awt.geom.Point2D;
import java.util.Map;
import net.runelite.client.game.ItemManager;

/** Shared reel-cell drawing used by both the world overlay and the horizontal top-centre overlay. */
final class Reels
{
	static final int SPIN_RADIUS = 23;
	static final int LAND_RADIUS = 32;

	private static final Color NOTHING = new Color(120, 120, 120);

	private Reels()
	{
	}

	static Color colourFor(int itemId, Map<Integer, Color> palette)
	{
		if (itemId == LoulettePlugin.NOTHING_ID)
		{
			return Rarity.NEUTRAL;
		}
		return palette.getOrDefault(itemId, Rarity.NEUTRAL);
	}

	/** Radial rarity glow behind an item. */
	static void glow(Graphics2D g, int itemId, Map<Integer, Color> palette, int cx, int cy, boolean strong, double scale)
	{
		if (itemId == LoulettePlugin.NOTHING_ID)
		{
			return;
		}
		final Color c = colourFor(itemId, palette);
		final int radius = (int) Math.round((strong ? LAND_RADIUS : SPIN_RADIUS) * scale);
		final int alpha = strong ? 215 : 130;
		final Paint old = g.getPaint();
		g.setPaint(new RadialGradientPaint(
			new Point2D.Float(cx, cy), radius,
			new float[]{0f, 1f},
			new Color[]{
				new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha),
				new Color(c.getRed(), c.getGreen(), c.getBlue(), 0)
			}));
		g.fillOval(cx - radius, cy - radius, radius * 2, radius * 2);
		g.setPaint(old);
	}

	static void symbol(Graphics2D g, ItemManager itemManager, int itemId, int quantity, int cx, int cy, double scale)
	{
		if (itemId == LoulettePlugin.NOTHING_ID)
		{
			final int r = (int) Math.round(9 * scale);
			g.setColor(NOTHING);
			g.setStroke(new BasicStroke(2));
			g.drawOval(cx - r, cy - r, r * 2, r * 2);
			g.drawLine(cx - r, cy + r, cx + r, cy - r);
			return;
		}
		final Image img = quantity > 1
			? itemManager.getImage(itemId, quantity, true)
			: itemManager.getImage(itemId);
		if (img == null)
		{
			return;
		}
		final int w = img.getWidth(null);
		final int h = img.getHeight(null);
		if (w <= 0 || h <= 0)
		{
			return;
		}
		final int dw = (int) Math.round(w * scale);
		final int dh = (int) Math.round(h * scale);
		g.drawImage(img, cx - dw / 2, cy - dh / 2, dw, dh, null);
	}
}

package com.github.diogogdias.loulette;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.GZIPInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Serves a monster's drop table. The primary source is a bundled snapshot of the entire OSRS Wiki
 * {@code dropsline} bucket (see {@code scripts/scrape-drops.mjs}), loaded once at startup — no network
 * request, always available. Monsters missing from the snapshot fall back to a live wiki fetch, but only
 * when the user opts in via {@link LouletteConfig#wikiDropTables()}.
 */
@Slf4j
@Singleton
class DropTableService
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	private static final int ROW_LIMIT = 300;
	private static final String SNAPSHOT = "drops.json.gz";
	private static final CompletableFuture<List<DropEntry>> EMPTY =
		CompletableFuture.completedFuture(Collections.emptyList());

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final LouletteConfig config;

	/** Bundled snapshot: lower-cased page name -> drop lines. Immutable after load. */
	private final Map<String, List<DropEntry>> bundled;

	/** Bundled item name (lower-cased) -> in-game id, covering untradeables ItemManager.search can't. */
	private final Map<String, Integer> itemIds;

	/** Bundled lower-cased page name -> the monster's unique drop names (wiki "Uniques" section). */
	private final Map<String, List<String>> uniqueNames;

	/** Bundled pet item names (lower-cased): drops OSRS rolls on a separate roll from the main table. */
	private final Set<String> pets;

	private final Map<String, CompletableFuture<List<DropEntry>>> cache = new ConcurrentHashMap<>();

	@Inject
	DropTableService(OkHttpClient okHttpClient, Gson gson, LouletteConfig config)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.config = config;
		final JsonObject root = loadRoot(gson);
		this.bundled = parseMonsters(root);
		this.itemIds = parseItemIds(root);
		this.uniqueNames = parseUniques(root);
		this.pets = parsePets(root);
	}

	/** True when an item name is a pet (rolled on its own roll, so it earns a dedicated reel). */
	boolean isPet(String name)
	{
		return name != null && pets.contains(name.toLowerCase());
	}

	/** Bundled in-game id for an item name, or -1 if it isn't in the snapshot. */
	int itemId(String name)
	{
		if (name == null)
		{
			return -1;
		}
		final Integer id = itemIds.get(name.toLowerCase());
		return id != null ? id : -1;
	}

	/** The monster's tagged unique drop names (wiki "Uniques" section), or empty if none are bundled. */
	List<String> uniqueNames(String monster)
	{
		if (monster == null)
		{
			return Collections.emptyList();
		}
		final String key = monster.toLowerCase();
		final List<String> names = uniqueNames.get(key);
		if (names != null)
		{
			return names;
		}
		return uniqueNames.getOrDefault(key + " (monster)", Collections.emptyList());
	}

	CompletableFuture<List<DropEntry>> table(String monster)
	{
		final String key = monster.toLowerCase();
		// The wiki disambiguates a monster sharing its name with an item (Manta ray, Monkey, Penguin, Rock golem…)
		// as "X (monster)", but the in-game NPC name is just "X". Fall back to that page when the plain name misses.
		final List<DropEntry> snapshot = bundled.containsKey(key) ? bundled.get(key) : bundled.get(key + " (monster)");
		if (snapshot != null)
		{
			return CompletableFuture.completedFuture(snapshot);
		}
		if (config.wikiDropTables())
		{
			return cache.computeIfAbsent(key, k -> request(monster));
		}
		return EMPTY;
	}

	/** Reads and parses the gzipped snapshot bundled in resources; null if it's missing or unreadable. */
	private static JsonObject loadRoot(Gson gson)
	{
		try (InputStream raw = DropTableService.class.getResourceAsStream(SNAPSHOT))
		{
			if (raw == null)
			{
				log.warn("Drop-table snapshot '{}' missing; relying on the live wiki fallback only", SNAPSHOT);
				return null;
			}
			try (InputStreamReader reader = new InputStreamReader(new GZIPInputStream(raw), StandardCharsets.UTF_8))
			{
				return gson.fromJson(reader, JsonObject.class);
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load drop-table snapshot '{}': {}", SNAPSHOT, e.getMessage());
			return null;
		}
	}

	/** Bundled snapshot -> immutable lower-cased page name -> drop-lines map. */
	private static Map<String, List<DropEntry>> parseMonsters(JsonObject root)
	{
		if (root == null || !root.has("monsters"))
		{
			return Collections.emptyMap();
		}
		final JsonObject monsters = root.getAsJsonObject("monsters");
		final Map<String, List<DropEntry>> out = new HashMap<>(monsters.size() * 2);
		for (Map.Entry<String, JsonElement> e : monsters.entrySet())
		{
			out.put(e.getKey(), Collections.unmodifiableList(parseLines(e.getValue().getAsJsonArray())));
		}
		log.debug("Loaded drop-table snapshot: {} monsters (updated {})",
			out.size(), root.has("lastUpdated") ? root.get("lastUpdated").getAsString() : "?");
		return Collections.unmodifiableMap(out);
	}

	/** Bundled snapshot -> immutable lower-cased item name -> in-game id map. */
	private static Map<String, Integer> parseItemIds(JsonObject root)
	{
		if (root == null || !root.has("items") || !root.get("items").isJsonObject())
		{
			return Collections.emptyMap();
		}
		final JsonObject items = root.getAsJsonObject("items");
		final Map<String, Integer> out = new HashMap<>(items.size() * 2);
		for (Map.Entry<String, JsonElement> e : items.entrySet())
		{
			out.put(e.getKey(), e.getValue().getAsInt());
		}
		return Collections.unmodifiableMap(out);
	}

	/** Bundled snapshot -> immutable lower-cased page name -> unique drop names map. */
	private static Map<String, List<String>> parseUniques(JsonObject root)
	{
		if (root == null || !root.has("uniques") || !root.get("uniques").isJsonObject())
		{
			return Collections.emptyMap();
		}
		final JsonObject uniques = root.getAsJsonObject("uniques");
		final Map<String, List<String>> out = new HashMap<>(uniques.size() * 2);
		for (Map.Entry<String, JsonElement> e : uniques.entrySet())
		{
			final JsonArray arr = e.getValue().getAsJsonArray();
			final List<String> names = new ArrayList<>(arr.size());
			for (int i = 0; i < arr.size(); i++)
			{
				names.add(arr.get(i).getAsString());
			}
			out.put(e.getKey(), Collections.unmodifiableList(names));
		}
		return Collections.unmodifiableMap(out);
	}

	/** Bundled snapshot -> immutable set of lower-cased pet item names. */
	private static Set<String> parsePets(JsonObject root)
	{
		if (root == null || !root.has("pets") || !root.get("pets").isJsonArray())
		{
			return Collections.emptySet();
		}
		final JsonArray arr = root.getAsJsonArray("pets");
		final Set<String> out = new HashSet<>(arr.size() * 2);
		for (int i = 0; i < arr.size(); i++)
		{
			out.add(arr.get(i).getAsString().toLowerCase());
		}
		return Collections.unmodifiableSet(out);
	}

	/**
	 * Each line is {@code [name, rarity]}, {@code [name, rarity, rolls]} or {@code [name, rarity, rolls, rdt]};
	 * rolls defaults to 1, and a trailing {@code 1} marks a rare/gem/mega drop-table row.
	 */
	private static List<DropEntry> parseLines(JsonArray lines)
	{
		final List<DropEntry> entries = new ArrayList<>(lines.size());
		for (int i = 0; i < lines.size(); i++)
		{
			final JsonArray line = lines.get(i).getAsJsonArray();
			final String name = line.get(0).getAsString();
			final String rarity = line.size() > 1 && !line.get(1).isJsonNull() ? line.get(1).getAsString() : "";
			final int rolls = line.size() > 2 ? Math.max(1, line.get(2).getAsInt()) : 1;
			final boolean rdt = line.size() > 3 && line.get(3).getAsInt() == 1;
			entries.add(new DropEntry(name, "Always".equalsIgnoreCase(rarity), rolls, parseChance(rarity), rdt));
		}
		return entries;
	}

	private CompletableFuture<List<DropEntry>> request(String monster)
	{
		final CompletableFuture<List<DropEntry>> future = new CompletableFuture<>();

		final String query = "bucket('dropsline').select('item_name','drop_json')"
			+ ".where('page_name','" + monster.replace("'", "\\'") + "')"
			+ ".limit(" + ROW_LIMIT + ").run()";

		final HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		final Request req = new Request.Builder()
			.url(url)
			.header("User-Agent", "loulette RuneLite plugin")
			.build();

		okHttpClient.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Drop table fetch failed for '{}': {}", monster, e.getMessage());
				future.complete(new ArrayList<>());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					future.complete(parse(r, monster));
				}
				catch (Exception e)
				{
					log.debug("Drop table parse failed for '{}': {}", monster, e.getMessage());
					future.complete(new ArrayList<>());
				}
			}
		});

		return future;
	}

	private List<DropEntry> parse(Response response, String monster) throws IOException
	{
		final List<DropEntry> entries = new ArrayList<>();
		if (!response.isSuccessful() || response.body() == null)
		{
			return entries;
		}

		final JsonObject root = gson.fromJson(response.body().charStream(), JsonObject.class);
		if (root == null || !root.has("bucket") || !root.get("bucket").isJsonArray())
		{
			return entries;
		}

		final JsonArray rows = root.getAsJsonArray("bucket");
		for (int i = 0; i < rows.size(); i++)
		{
			final JsonObject row = rows.get(i).getAsJsonObject();
			if (!row.has("item_name") || row.get("item_name").isJsonNull())
			{
				continue;
			}
			final String name = row.get("item_name").getAsString().trim();
			if (name.isEmpty() || "Nothing".equalsIgnoreCase(name))
			{
				continue;
			}

			boolean always = false;
			int rolls = 1;
			double chance = -1;
			if (row.has("drop_json") && !row.get("drop_json").isJsonNull())
			{
				try
				{
					final JsonObject dj = gson.fromJson(row.get("drop_json").getAsString(), JsonObject.class);
					final String rarity = optString(dj, "Rarity");
					always = "Always".equalsIgnoreCase(rarity);
					rolls = Math.max(1, optInt(dj, "Rolls", 1));
					chance = parseChance(rarity);
				}
				catch (Exception ignored)
				{
					// keep defaults
				}
			}
			// The live fallback fetches a single monster, so there's no cross-row context to detect the
			// shared rare/gem/mega drop table; those rows are left in for unbundled monsters.
			entries.add(new DropEntry(name, always, rolls, chance, false));
		}

		log.debug("Drop table for '{}': {} lines", monster, entries.size());
		return entries;
	}

	private static String optString(JsonObject o, String key)
	{
		final JsonElement e = o.get(key);
		return e == null || e.isJsonNull() ? "" : e.getAsString();
	}

	/** Parses a wiki rarity string ("1/128", "3/128", "~1/5,000", "Always") into a probability; -1 if unknown. */
	private static double parseChance(String rarity)
	{
		if (rarity == null)
		{
			return -1;
		}
		final String r = rarity.replace(",", "").replace("~", "").trim().toLowerCase();
		if (r.equals("varies") || r.equals("random"))
		{
			return Double.NaN;
		}
		if (r.isEmpty() || r.equals("unknown"))
		{
			return -1;
		}
		if (r.equals("always"))
		{
			return 1.0;
		}
		final int slash = r.indexOf('/');
		if (slash > 0)
		{
			try
			{
				final double num = Double.parseDouble(r.substring(0, slash).trim());
				final double den = Double.parseDouble(r.substring(slash + 1).trim());
				return den > 0 ? num / den : -1;
			}
			catch (NumberFormatException ex)
			{
				return -1;
			}
		}
		switch (r)
		{
			case "common":
				return 1 / 12.0;
			case "uncommon":
				return 1 / 60.0;
			case "rare":
				return 1 / 400.0;
			case "very rare":
				return 1 / 2000.0;
			default:
				return -1;
		}
	}

	private static int optInt(JsonObject o, String key, int def)
	{
		final JsonElement e = o.get(key);
		if (e == null || e.isJsonNull())
		{
			return def;
		}
		try
		{
			return e.getAsInt();
		}
		catch (NumberFormatException ex)
		{
			return def;
		}
	}
}

